action.code:
size_t bucket_count = ZU(1) << ckh->lg_curbuckets;
for (size_t i = 0; i < bucket_count; i++) {
    for (size_t j = 0; j < (ZU(1) << LG_CKH_BUCKET_CELLS); j++) {
        size_t idx = ckh_cell_index(i, j);
        if (aTab[idx].key != nullptr) {
            ckh->hash(aTab[idx].key, ckh->prng_state);
            ckh_try_insert(ckh, aTab[idx].key, aTab[idx].data);
        }
    }
}
ckh->tab = aTab;

